package io.github.miklires.mclans.clan;
import java.util.Locale;import java.util.Set;import java.util.regex.Pattern;
public final class ClanNamingPolicy {private final Pattern name;private final Pattern tag;private final Set<String> reserved;public ClanNamingPolicy(String nameRegex,String tagRegex,Set<String> reserved){name=Pattern.compile(nameRegex);tag=Pattern.compile(tagRegex);this.reserved=reserved.stream().map(s->s.toLowerCase(Locale.ROOT)).collect(java.util.stream.Collectors.toUnmodifiableSet());}public Result validate(String candidate,String candidateTag){if(!name.matcher(candidate).matches())return Result.BAD_NAME;if(!tag.matcher(candidateTag).matches())return Result.BAD_TAG;if(reserved.contains(candidate.toLowerCase(Locale.ROOT))||reserved.contains(candidateTag.toLowerCase(Locale.ROOT)))return Result.RESERVED;return Result.ALLOWED;}public enum Result{ALLOWED,BAD_NAME,BAD_TAG,RESERVED}}
